}
$products=$db->query('SELECT p.*,c.name category FROM products p JOIN categories c ON c.id=p.category_id WHERE p.is_available=1 ORDER BY p.is_special DESC,p.name')->fetchAll();
$categories=array_values(array_unique(array_column($products,'category')));
$count=array_sum($_SESSION['cart']);
